   "code": "// Power of two choices, simulated against plain random choice\nfunction simulate(pick, servers = 20, requests = 100000) {\n  const load = Array(servers).fill(0);\n  for (let i = 0; i < requests; i++) load[pick(load)]++;\n  return Math.max(...load) - requests / servers;      // how far the busiest server is above average\n}\nconst rnd = n => Math.floor(Math.random() * n);\nconst random = load => rnd(load.length);\nconst twoChoices = load => { const a = rnd(load.length), b = rnd(load.length); return load[a] <= load[b] ? a : b; };\nconsole.log('random  : busiest is', simulate(random), 'over average');\nconsole.log('2 choices: busiest is', simulate(twoChoices), 'over average');",
