   "code": "function instancesNeeded({ peakRps, serviceMs, perInstanceConcurrency, targetUtil = 0.6, zones = 3 }) {\n  const concurrency = peakRps * serviceMs / 1000;                       // Little's Law\n  const base = Math.ceil(concurrency / (perInstanceConcurrency * targetUtil));\n  const zoneSafe = Math.ceil(base * zones / (zones - 1));             // survive losing one zone\n  return { concurrency, base, zoneSafe };\n}\nconsole.log(instancesNeeded({ peakRps: 6000, serviceMs: 40, perInstanceConcurrency: 50 }));\n// { concurrency: 240, base: 8, zoneSafe: 12 }",
