   "code": "# Kubernetes HorizontalPodAutoscaler: fast up, slow down, with limits\napiVersion: autoscaling/v2\nkind: HorizontalPodAutoscaler\nmetadata: { name: api }\nspec:\n  scaleTargetRef: { apiVersion: apps/v1, kind: Deployment, name: api }\n  minReplicas: 6          # covers a zone loss at the night-time baseline\n  maxReplicas: 40         # protects the database and the bill\n  metrics:\n    - type: Resource\n      resource: { name: cpu, target: { type: Utilization, averageUtilization: 60 } }\n  behavior:\n    scaleUp:   { stabilizationWindowSeconds: 0,   policies: [{ type: Percent, value: 100, periodSeconds: 30 }] }\n    scaleDown: { stabilizationWindowSeconds: 600, policies: [{ type: Percent, value: 10,  periodSeconds: 60 }] }",
